        self.type_ = type_
        self.value = value

def tokenize(expr: str):
    tokens = []
    i = 0
    while i < len(expr):
        char = expr[i]
        if char.isspace():
            i += 1
            continue
        if char in '+-*/()':
            tokens.append(Token('OPERATOR', char))
            i += 1
            continue
        if char.isdigit() or (char == '.' and i + 1 < len(expr) and expr[i + 1].isdigit()):
            j = i
            while j < len(expr) and (expr[j].isdigit() or expr[j] == '.'):
                j += 1
            tokens.append(Token('NUMBER', float(expr[i:j])))
            i = j
            continue
        raise ValueError(f"Unexpected character: {char}")
    return tokens

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def parse(self):
        return self.expr()

    def expr(self):
        result = self.term()
        while self.pos < len(self.tokens) and self.tokens[self.pos].value in ('+', '-'):
            op = self.tokens[self.pos].value
            self.pos += 1
            if op == '+':
                result += self.term()
            else:
                result -= self.term()
        return result

    def term(self):
        result = self.factor()
        while self.pos < len(self.tokens) and self.tokens[self.pos].value in ('*', '/'):
            op = self.tokens[self.pos].value
            self.pos += 1
            if op == '*':
                result *= self.factor()
            else:
                result /= self.factor()
        return result

    def factor(self):
        token = self.tokens[self.pos]
        if token.type_ == 'NUMBER':
            self.pos += 1
            return token.value
        elif token.value == '(':
            self.pos += 1
            result = self.expr()
            if self.tokens[self.pos].value != ')':
                raise ValueError("Expected ')'")
            self.pos += 1
            return result
        raise ValueError("Unexpected token")

def evaluate(expr: str) -> float:
    """Evaluates a mathematical expression using a recursive descent parser."""
    tokens = tokenize(expr)
    parser = Parser(tokens)
    return parser.parse()

class TokenType:
    NUMBER = 'NUMBER'
    PLUS = 'PLUS'
    MINUS = 'MINUS'
    MULTIPLY = 'MULTIPLY'
    DIVIDE = 'DIVIDE'
    LPAREN = 'LPAREN'
    RPAREN = 'RPAREN'
    END = 'END'


class Token:
    def __init__(self, type_, value):
        self.type_ = type_
        self.value = value


class Lexer:
    def __init__(self, expr):
        self.expr = expr
        self.position = 0

    def get_next_token(self):
        if self.position >= len(self.expr):
            return Token(TokenType.END, None)

        char = self.expr[self.position]

        if char.isspace():
            self.position += 1
            return self.get_next_token()

        if char.isdigit() or char == '.':
            start = self.position
            while (self.position < len(self.expr) and
                   (self.expr[self.position].isdigit() or self.expr[self.position] == '.')):
                self.position += 1
            return Token(TokenType.NUMBER, float(self.expr[start:self.position]))

        if char == '+':
            self.position += 1
            return Token(TokenType.PLUS, '+')
        if char == '-':
            self.position += 1
            return Token(TokenType.MINUS, '-')
        if char == '*':
            self.position += 1
            return Token(TokenType.MULTIPLY, '*')
        if char == '/':
            self.position += 1
            return Token(TokenType.DIVIDE, '/')
        if char == '(':
            self.position += 1
            return Token(TokenType.LPAREN, '(')
        if char == ')':
            self.position += 1
            return Token(TokenType.RPAREN, ')')

        raise ValueError(f"Invalid character: {char}")


class Parser:
    def __init__(self, lexer):
        self.lexer = lexer
        self.current_token = self.lexer.get_next_token()

    def error(self):
        raise Exception("Invalid syntax")

    def eat(self, token_type):
        if self.current_token.type_ == token_type:
            self.current_token = self.lexer.get_next_token()
        else:
            self.error()

    def factor(self):
        token = self.current_token
        if token.type_ == TokenType.NUMBER:
            self.eat(TokenType.NUMBER)
            return token.value
        elif token.type_ == TokenType.LPAREN:
            self.eat(TokenType.LPAREN)
            result = self.expr()
            self.eat(TokenType.RPAREN)
            return result
        self.error()

    def term(self):
        result = self.factor()
        while self.current_token.type_ in (TokenType.MULTIPLY, TokenType.DIVIDE):
            token = self.current_token
            if token.type_ == TokenType.MULTIPLY:
                self.eat(TokenType.MULTIPLY)
                result *= self.factor()
            elif token.type_ == TokenType.DIVIDE:
                self.eat(TokenType.DIVIDE)
                result /= self.factor()
        return result

    def expr(self):
        result = self.term()
        while self.current_token.type_ in (TokenType.PLUS, TokenType.MINUS):
            token = self.current_token
            if token.type_ == TokenType.PLUS:
                self.eat(TokenType.PLUS)
                result += self.term()
            elif token.type_ == TokenType.MINUS:
                self.eat(TokenType.MINUS)
                result -= self.term()
        return result


