def evaluate(expr: str) -> float:
    """
    Evaluates an arithmetic expression using the Shunting Yard algorithm for parsing
    and a stack-based evaluation method for computing the result. This ensures correct
    operator precedence and supports parentheses.
    """

    def precedence(op: str) -> int:
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_operator(operators: list, values: list) -> None:
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(left / right)

    def shunting_yard(expression: str) -> float:
        values = []
        operators = []
        i = 0
        n = len(expression)

        while i < n:
            if expression[i].isspace():
                i += 1
                continue
            if expression[i].isdigit() or expression[i] == '.':
                num = ''
                while i < n and (expression[i].isdigit() or expression[i] == '.'):
                    num += expression[i]
                    i += 1
                values.append(float(num))
                continue
            if expression[i] == '(':
                operators.append(expression[i])
            elif expression[i] == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operators, values)
                operators.pop()  # Pop the '('
            else:
                while (operators and 
                       precedence(operators[-1]) >= precedence(expression[i])):
                    apply_operator(operators, values)
                operators.append(expression[i])
            i += 1

        while operators:
            apply_operator(operators, values)

        return values[0]

    return shunting_yard(expr)
